insert:
id: infoMain
color: "black"
property string modelName
property string softwareVersion
property string memorySize
/** type:var SDカードのタイトルとサイズリスト */
property var sd_card_info_list
property string contentsCount
property string workTime
property string btAddress
property bool isAvailableWifi
property bool isAvailablePlaybackTimeCounter
property string copyright
property int scrollRightMargin: 4
readonly property int flickableAreaMaxHeight: 612
property int firstPressedPositionY: -1
readonly property int visibleAnimationDuration: 100
readonly property int invisibleAnimationDuration: 0
property bool isMovingUp: false
property bool isMovingDown: false
function setState()
{
if (flickableAreaMaxHeight >= flickableArea.contentHeight) {
if (isMovingUp) {
state = "TopEdgeOn"
} else if (isMovingDown) {
state = "BottomEdgeOn"
} else {
state = "EdgeOff"

return
}
if (flickableArea.atYBeginning && (isMovingUp || flickableArea.movingVertically)) {
state = "TopEdgeOn"
} else if (flickableArea.atYBeginning && !isMovingUp && !flickableArea.movingVertically) {
state = "EdgeOff"
} else if (flickableArea.atYEnd && (isMovingDown || flickableArea.movingVertically)) {
state = "BottomEdgeOn"
} else if (flickableArea.atYEnd && !isMovingDown && !flickableArea.movingVertically) {
state = "EdgeOff"
} else {
state = ""
}
}
function onReleased()
{
isMovingUp = false
isMovingDown = false
firstPressedPositionY = -1
setState()
}
function pressedYPosition(posY)
{
firstPressedPositionY = posY
}
function movingYPosition(posY) {
if (firstPressedPositionY === -1) {
isMovingUp = false
isMovingDown = false
return
}
if ((firstPressedPositionY - posY) < 0) {
isMovingUp = true
isMovingDown = false
} else if ((firstPressedPositionY - posY) > 0) {
isMovingUp = false
isMovingDown = true
} else {
isMovingUp = false
isMovingDown = false
}
setState()
}
states: [
State {
name: "TopEdgeOn"
PropertyChanges { target: topImage; opacity: 1; }
PropertyChanges { target: bottomImage; opacity: 0; }
},
State {
name: "BottomEdgeOn"
PropertyChanges { target: topImage; opacity: 0; }
PropertyChanges { target: bottomImage; opacity: 1; }
},
State {
name: "EdgeOff"
PropertyChanges { target: topImage; opacity: 0; }
PropertyChanges { target: bottomImage; opacity: 0; }
},
State {
name: "None"
PropertyChanges { target: topImage; opacity: 0; }
PropertyChanges { target: bottomImage; opacity: 0; }
}
]
transitions: [
Transition {
to: "TopEdgeOn"
PropertyAnimation { target: topImage; property: "opacity"; duration: visibleAnimationDuration; }
PropertyAnimation { target: bottomImage; property: "opacity"; duration: invisibleAnimationDuration; }
},
Transition {
to: "BottomEdgeOn"
PropertyAnimation { target: topImage; property: "opacity"; duration: invisibleAnimationDuration; }
PropertyAnimation { target: bottomImage; property: "opacity"; duration: visibleAnimationDuration; }
},
Transition {
to: "EdgeOff"
PropertyAnimation { target: topImage; property: "opacity"; duration: visibleAnimationDuration; }
PropertyAnimation { target: bottomImage; property: "opacity"; duration: visibleAnimationDuration; }
},
Transition {
to: "None"
PropertyAnimation { target: topImage; property: "opacity"; duration: invisibleAnimationDuration; }
PropertyAnimation { target: bottomImage; property: "opacity"; duration: invisibleAnimationDuration; }
}
]
Connections {
target: controller
onAvailable: {
flickableArea.contentY = 0
}
}
ScreenTitleArea {
id: deviceInfoTitleArea
z: 11
titleText: qsTr("010008") + viewstyle.empty_string
visibleMusicLibraryTopicon: false
fontWeight: Font.Light
}
Flickable {
id: flickableArea
contentWidth: 480
contentHeight: flickable.y + flickable.height
width: 480
height: infoMain.height - deviceInfoTitleArea.height
y: deviceInfoTitleArea.height
contentY: 0
interactive: (contentHeight > height) ? true : false
boundsBehavior: Flickable.StopAtBounds
onAtYBeginningChanged: infoMain.setState()
onAtYEndChanged: infoMain.setState()
onMovingVerticallyChanged: infoMain.setState()
Column {
id: flickable
width: 480
SettingItemInfo {
title: qsTr("010009") + viewstyle.empty_string
info: modelName
onEdgeReleased: infoMain.onReleased()
onEdgeCanceled: infoMain.onReleased()
onPressedYPosition: infoMain.pressedYPosition(posY)
onMovedYPosition: infoMain.movingYPosition(posY)
}
SettingItemInfo {
title: qsTr("010010") + viewstyle.empty_string
info: softwareVersion
infoLineTwo: copyright
onEdgeReleased: infoMain.onReleased()
onEdgeCanceled: infoMain.onReleased()
onPressedYPosition: infoMain.pressedYPosition(posY)
onMovedYPosition: infoMain.movingYPosition(posY)
}
SettingItemInfo {
title: "Installed patch"
info: "Patchman v1.1"
onEdgeReleased: infoMain.onReleased()
onEdgeCanceled: infoMain.onReleased()
onPressedYPosition: infoMain.pressedYPosition(posY)
onMovedYPosition: infoMain.movingYPosition(posY)
}
SettingItemInfo {
title: qsTr("010013") + viewstyle.empty_string
info: memorySize
onEdgeReleased: infoMain.onReleased()
onEdgeCanceled: infoMain.onReleased()
onPressedYPosition: infoMain.pressedYPosition(posY)
onMovedYPosition: infoMain.movingYPosition(posY)
}
Repeater {
model: sd_card_info_list
SettingItemInfo {
title: model.title
info: model.info
onEdgeReleased: infoMain.onReleased()
onEdgeCanceled: infoMain.onReleased()
onPressedYPosition: infoMain.pressedYPosition(posY)
onMovedYPosition: infoMain.movingYPosition(posY)
}
}
SettingItemInfo {
title: qsTr("010012") + viewstyle.empty_string
info: contentsCount
onEdgeReleased: infoMain.onReleased()
onEdgeCanceled: infoMain.onReleased()
onPressedYPosition: infoMain.pressedYPosition(posY)
onMovedYPosition: infoMain.movingYPosition(posY)
}
SettingItemInfo {
visible: isAvailablePlaybackTimeCounter
title: qsTr("010018") + viewstyle.empty_string
info: workTime
onEdgeReleased: infoMain.onReleased()
onEdgeCanceled: infoMain.onReleased()
onPressedYPosition: infoMain.pressedYPosition(posY)
onMovedYPosition: infoMain.movingYPosition(posY)
}
SettingItemInfo {
title: qsTr("010015") + viewstyle.empty_string
info: btAddress
onEdgeReleased: infoMain.onReleased()
onEdgeCanceled: infoMain.onReleased()
onPressedYPosition: infoMain.pressedYPosition(posY)
onMovedYPosition: infoMain.movingYPosition(posY)
}
}
}
SCmnScrollIndicator {
id: scroll
anchors {
top: flickableArea.top
bottom: flickableArea.bottom
right: flickableArea.right
rightMargin: scrollRightMargin
}
z: 10
flickable: flickableArea
visible: (flickableArea.contentHeight > flickableArea.height) ? true : false
}
MouseArea {
id: mouseArea
visible: (flickableAreaMaxHeight >= flickableArea.height) ? true : false
anchors.top: flickableArea.bottom
anchors.left: flickableArea.left
anchors.right: flickableArea.right
anchors.bottom: infoMain.bottom
onReleased: infoMain.onReleased()
onCanceled: infoMain.onReleased()
onPressed: infoMain.pressedYPosition(mouse.y)
onMouseYChanged: infoMain.movingYPosition(mouse.y)
}
Image {
id: topImage
anchors { top: flickableArea.top; left: flickableArea.left; right: flickableArea.right; }
source: "qrc:/ic_list_full_end_mask_upper.png"
height: sourceSize.height
opacity: 0
}
Image {
id: bottomImage
anchors { bottom: mouseArea.bottom; left: flickableArea.left; right: flickableArea.right; }
source: "qrc:/ic_list_full_end_mask_lower.png"
height: sourceSize.height
opacity: 0
}
}
